function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function parseAgents(t){
  return splitLines(t).map(function(l){
    var p=l.split('|').map(function(c){return c.trim();});
    return {role:p[0]||'（待命名角色）', duty:p[1]||'（待补充职责）', bound:p[2]||'（待补充边界）', handoff:p[3]||'（待补充交接）'};
  });
}
function buildRoleCards(o){
  o=o||{};
  var team=String(o.team||'').trim()||'（待命名团队）';
  var agents=parseAgents(o.agents);
  if(!agents.length) agents=[{role:'（示例角色）',duty:'（待补充职责）',bound:'（待补充边界）',handoff:'（待补充交接）'}];
  var lines=[];
  lines.push('# 多 Agent 团队角色卡：'+team);
  lines.push('');
  lines.push('## 团队总览');
  lines.push('| 角色 | 核心职责 | 边界 | 交接 |');
  lines.push('| --- | --- | --- | --- |');
  agents.forEach(function(a){ lines.push('| '+a.role+' | '+a.duty+' | '+a.bound+' | '+a.handoff+' |'); });
  lines.push('');
  lines.push('## 角色详卡');
  agents.forEach(function(a){
    lines.push('### '+a.role);
    lines.push('- 职责：'+a.duty);
    lines.push('- 边界：'+a.bound);
    lines.push('- 交接：'+a.handoff);
    lines.push('');
  });
  return {title:team+' 角色卡', agentCount:agents.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, parseAgents:parseAgents, buildRoleCards:buildRoleCards};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AgentRoleCardForgePure = EXPORTS; }
